-- ============================================================================
-- find_confusable_prec_pairs.sql
-- 서로 다른 사건인데 판시사항 요약(head) 문구가 유사한 판례 쌍을 찾습니다.
-- "기망행위", "편취의 고의" 같은 법리 설시는 사건이 달라도 거의 동일하게
-- 반복되는 경우가 많아, law의 목적조항 보일러플레이트와 같은 위험이 있습니다.
-- prec chunk_id 구조: prec_{case_no}_head_{n} (요약), prec_{case_no}_body_{n} (본문)
-- ============================================================================

-- [1] 요약(head_1) 문구끼리 서로 다른 사건인데 트라이그램 유사도가 높은 쌍
--     ROUND로 소수점을 명시해서 지난번 같은 반올림 착시를 방지합니다.
SELECT
    a.chunk_id AS chunk_a,
    a.title    AS title_a,
    b.chunk_id AS chunk_b,
    b.title    AS title_b,
    ROUND(similarity(a.content, b.content)::numeric, 4) AS content_similarity
FROM legal_chunks a
JOIN legal_chunks b
  ON a.doc_type = 'prec'
 AND b.doc_type = 'prec'
 AND a.doc_id < b.doc_id
 AND a.chunk_id LIKE '%\_head\_1'
 AND b.chunk_id LIKE '%\_head\_1'
WHERE similarity(a.content, b.content) > 0.35
ORDER BY content_similarity DESC
LIMIT 40;

